content.text:
{
  "ok": true,
  "op": "grant_request",
  "run_id": "r-mux-1",
  "card": {
    "shape": "F.0",
    "title": "See every search before it leaves, then approve this run once.",
    "question": "Send these 3 searches to OpenAlex for this run?",
    "options": [
      {
        "id": "approve_run",
        "label": "Send these 3 searches (Recommended)",
        "recommended": true
      },
      {
        "id": "not_now",
        "label": "Not now",
        "recommended": false
      }
    ],
    "body_md": "These 3 searches will leave this machine for market sizing for this room. Nothing is sent until you approve.\n\nThe searches, exactly as they will be sent:\n- market sizing for thin-film milk sensors\n- thin-film sensor milk quality literature\n- dairy sensor market analysis\n\nApproving never files anything.",
    "payload": {
      "grant_lifetime": "run",
      "queries": [
        "market sizing for thin-film milk sensors",
        "thin-film sensor milk quality literature",
        "dairy sensor market analysis"
      ],
      "job": "market sizing for this room"
    }
  },
  "new_terms": [],
  "gate": {
    "gate_id": "g-mux-1",
    "renderer": "askuserquestion",
    "rendered": {
      "zones": {
        "header": "See every search before it leaves, then approve this run once. Send these 3 searches to OpenAlex for this run?"
      },
      "contract": {
        "shape": "F.8",
        "multiSelect": false
      }
    }
  },
  "next_step": "Show the card. When the navigator answers, call gate_answer with this gate_id. Nothing is saved until then."
}

